<?php
namespace App\Console\Commands;use Illuminate\Console\Command;
class WarehouseV2BackfillAllCommand extends Command{protected $signature='warehouse:v2-backfill-all {--limit=500}';protected $description='Menjalankan backfill invoice Warehouse v2 secara aman';public function handle():int{$limit=(int)$this->option('limit');$commands=[['warehouse:finance-backfill-invoices',['--limit'=>$limit]],['warehouse:purchasing-backfill-invoices',['--limit'=>$limit]]];foreach($commands as[$name,$args]){if(!$this->getApplication()?->has($name)){$this->warn("Command {$name} tidak tersedia; dilewati.");continue;}$this->info("Menjalankan {$name}");$code=$this->call($name,$args);if($code!==self::SUCCESS)return$code;}$this->info('Backfill Warehouse v2 selesai. Jalankan reconciliation dan go-live gate.');return self::SUCCESS;}}
